//! Generator targets. Each target turns Java sources into a list of [`Output`] files.
//!
//! To add a target: create `targets/<name>.rs` with a `generate(&JavaSources) -> Result<Vec<Output>>`
//! style function (see `opcodes.rs`, the reference), add it to [`Target`] and to `run` in `main.rs`.

pub mod config;
pub mod messages;
pub mod opcodes;

use anyhow::Result;
use quote::ToTokens;
use std::path::PathBuf;

/// Header of every generated file. CI and reviewers grep for it.
pub const HEADER: &str = "// @generated by codegen — do not edit";

/// One file the generator wants on disk.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Output {
    /// Path relative to the workspace root, with `/` separators.
    pub path: PathBuf,
    pub contents: String,
}

/// Modules in `crates/l2-protocol-game/src/generated/`. A generator for that crate adds its module
/// name here, so `generated/mod.rs` always lists every generated file.
pub const GAME_GENERATED_MODS: &[&str] = &["npc_string_id", "opcodes", "system_message_id"];

/// Renders a token stream as formatted Rust source, with the generated-file header.
///
/// Uses `prettyplease`, so the output is deterministic. `rustfmt` would reformat prettyplease's
/// layout (blank lines between items), which would make `cargo fmt` and the `--check` step fight.
/// So the `mod` line that declares a generated file carries `#[rustfmt::skip]` (inner attributes
/// like `#![rustfmt::skip]` are unstable). Every new generated module must be declared that way;
/// `game_generated_mod` does it for the game protocol crate.
pub fn render(source_note: &str, tokens: impl ToTokens) -> Result<String> {
    let file: syn::File = syn::parse2(tokens.into_token_stream())?;
    let body = prettyplease::unparse(&file);
    Ok(format!("{HEADER}\n{source_note}\n\n{body}"))
}

/// `generated/mod.rs` for the game protocol crate.
pub fn game_generated_mod() -> Result<Output> {
    let mods = GAME_GENERATED_MODS.iter().map(|m| quote::format_ident!("{m}"));
    let tokens = quote::quote! { #(#[rustfmt::skip] pub mod #mods;)* };
    Ok(Output {
        path: "crates/l2-protocol-game/src/generated/mod.rs".into(),
        contents: render(
            "// Lists every generated module of this crate (see codegen `GAME_GENERATED_MODS`).",
            tokens,
        )?,
    })
}
